#!/bin/bash
# Generated by hpc-runner (SGE scheduler)

#$ -S /bin/bash
#$ -cwd
#$ -V
#$ -N train
#$ -pe smp 4
#$ -l h_vmem=4G
#$ -l h_rt=4:00:00
#$ -o /work/logs/$JOB_NAME.$JOB_ID.out
#$ -e /work/logs/$JOB_NAME.$JOB_ID.err

# Exit on error
set -e

# --- hpc-runner: publish this job's exit code (NFS-safe) ---
# SGE -hold_jid is afterany, so dependents read these sentinels to emulate
# afterok/afternotok. An array task publishes its own <JOB_ID>.<TASK>.rc.
# SGE sets SGE_TASK_ID=undefined for a non-array job, so treat that as unset.
# The EXIT trap fires on success, `set -e` failure, and the guard below, so
# the exit code is always published. Write-then-rename is atomic on NFS so a
# reader never sees a partial value.
_hpc_exit_dir=/shared/hpc-runner/exit
_hpc_task="${SGE_TASK_ID:-}"; [ "$_hpc_task" = undefined ] && _hpc_task=""; _hpc_rc_name="${JOB_ID}${_hpc_task:+.$_hpc_task}.rc"
mkdir -p "$_hpc_exit_dir"
_hpc_on_exit() {
    local _ec=$?
    { printf '%s\n' "$_ec" > "$_hpc_exit_dir/.${_hpc_rc_name}.$$" \
        && mv -f "$_hpc_exit_dir/.${_hpc_rc_name}.$$" "$_hpc_exit_dir/${_hpc_rc_name}" ; } 2>/dev/null || true
    if [ -n "${_hpc_modlog:-}" ]; then rm -f "$_hpc_modlog"; fi
    return "$_ec"
}
trap _hpc_on_exit EXIT

# --- hpc-runner environment ---
# Module system initialization
. /site/modules/init.sh
export MODULES_VERBOSITY=concise

# Module commands are quiet on success; their output is shown if one fails.
_hpc_modlog=$(mktemp)

# Purge modules for a clean environment
module purge 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module purge failed' >&2; exit 1; }

# Additional module paths
module use /site/modulefiles 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module use /site/modulefiles failed' >&2; exit 1; }

# Additional module paths, searched after the existing MODULEPATH
module use --append /home/alice/modulefiles 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module use --append /home/alice/modulefiles failed' >&2; exit 1; }

# Load modules
module load gcc/12 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module load gcc/12 failed' >&2; exit 1; }
module load python/3.11 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module load python/3.11 failed' >&2; exit 1; }
module load cuda/12.2 2>"$_hpc_modlog" || { cat "$_hpc_modlog" >&2; echo 'hpc-runner: module load cuda/12.2 failed' >&2; exit 1; }

# Activate virtual environment
source .venv/bin/activate

# Unset environment variables
unset http_proxy

# Prepend to environment variables
export PATH=/opt/tools/bin${PATH:+:$PATH}

# Append to environment variables
export PYTHONPATH=${PYTHONPATH:+$PYTHONPATH:}/work/lib

# Set environment variables
export PYTHONUNBUFFERED=1
export MAKEFLAGS=-j"$NSLOTS"
export GREETING='it'"'"'s $5 "quoted"'
# --- end hpc-runner environment ---

# Execute command
python train.py --label 'my run'
_exit_code=$?


exit $_exit_code
